{
  "work_definition_version": 0,
  "task_family": "reconciliation",
  "model_id": "vendor-charge-reconciliation-v1",
  "provenance": {
    "producer": "goose-w1i-u3",
    "skill": "define-lab-process",
    "produced_at": "2026-08-21"
  },
  "purpose": "Reconcile vendor charge summary with internal charge ledger by matching on Client Ref and comparing Net Value within tolerance of 0.01",
  "sources": {
    "supplier_statement": {
      "role_label": "Vendor Charge Summary",
      "fixture": "vendor-charge-summary.txt",
      "observed_fields": ["Charge Period", "Client Ref", "Net Value", "Tax Band", "Settlement State"],
      "basis": "observed"
    },
    "internal_ledger": {
      "role_label": "Internal Charge Ledger",
      "fixture": "internal-charge-ledger.txt",
      "observed_fields": ["Charge Period", "Internal Key", "Client Ref", "Net Value", "Settlement State", "Remarks"],
      "basis": "observed"
    }
  },
  "body": {
    "left": "supplier_statement",
    "right": "internal_ledger",
    "match_on": {
      "left_field": "Client Ref",
      "right_field": "Client Ref",
      "basis": "human_confirmed",
      "confirmation": "Q_match_key"
    },
    "compare": [
      {
        "field": "Net Value",
        "comparison": "within",
        "tolerance": "0.01",
        "basis": "human_confirmed",
        "confirmation": "Q_net_value"
      }
    ],
    "classify": {
      "both_same": "matched",
      "both_different": "value_difference",
      "only_left": "supplier_only",
      "only_right": "ledger_only"
    },
    "output_order": "sorted_by_key",
    "on_duplicate_key": "refuse_run",
    "on_non_numeric": "refuse_run"
  },
  "output": {
    "reports_fields": ["Client Ref", "Net Value"],
    "context_fields": ["Charge Period", "Settlement State"]
  },
  "human_confirmations": [
    {
      "id": "Q_match_key",
      "question": "Which field identifies the same record / charge line in both files?",
      "answer": "Client Ref",
      "basis": "human_confirmed"
    },
    {
      "id": "Q_net_value",
      "question": "Should Net Value be compared, and if so, how and with what tolerance?",
      "answer": "Yes, compare Net Value numerically, within 0.01.",
      "basis": "human_confirmed"
    },
    {
      "id": "Q_tax_band",
      "question": "Is Tax Band part of the reconciliation rule?",
      "answer": "No. Tax Band is recorded on the vendor side only; it is not compared and is not part of the rule.",
      "basis": "human_confirmed"
    },
    {
      "id": "Q_source_of_truth",
      "question": "Which file is the source of truth for matching?",
      "answer": "Neither — both are peer sources. Report what is missing from either side and differences in the compared field.",
      "basis": "human_confirmed"
    },
    {
      "id": "Q_report_fields",
      "question": "Which fields should appear in the report row?",
      "answer": "The match key (Client Ref) and the compared field (Net Value).",
      "basis": "human_confirmed"
    },
    {
      "id": "Q_context_fields",
      "question": "Which fields are context for the report?",
      "answer": "Charge Period and Settlement State.",
      "basis": "human_confirmed"
    }
  ],
  "open_questions": [],
  "requested_destination": "review_only",
  "requested_delivery": { "format": "json_discrepancy_report" }
}

